import * as THREE from 'three';

const $ = (s, root=document) => root.querySelector(s);
const $$ = (s, root=document) => [...root.querySelectorAll(s)];
const clamp = (v, a, b) => Math.max(a, Math.min(b, v));
const lerp = (a,b,t) => a+(b-a)*t;
const pick = arr => arr[Math.floor(Math.random()*arr.length)];
const SAVE_KEY = 'gxbr-save-v1';
const initialSave = {cash:2450, bike:0, owned:[0], paint:'#df493b', upgrades:{motor:0, exhaust:0, suspension:0}, outfit:'RUA', helmet:'PRETO FOSCO', graphics:'MÉDIO', sensitivity:1, fuel:82, gender:'MASCULINO', name:'RAFA', camera:0, sound:true, weather:0, hour:16.7, bestCombo:0};
let save; try { save={...initialSave,...JSON.parse(localStorage.getItem(SAVE_KEY)||'{}')}; } catch { save={...initialSave}; }
const persist=()=>{try{localStorage.setItem(SAVE_KEY,JSON.stringify(save));}catch{}};
const bikeData=[
 {name:'FALCÃO 160',class:'NAKED · 160 CC',power:'15,1',max:128,color:'#df493b',price:0,gears:5,handling:1},
 {name:'VÉRTICE 250',class:'STREET · 250 CC',power:'25,0',max:158,color:'#497b67',price:6800,gears:6,handling:.9},
