 {name:'PULSO 125',class:'URBANA · 125 CC',power:'11,0',max:108,color:'#e9e9df',price:0,gears:5,handling:1.15},
 {name:'RAIO 600',class:'ESPORTIVA · 600 CC',power:'74,0',max:220,color:'#6e74c8',price:22000,gears:6,handling:.76}
];
const state={speed:0,velocity:0,heading:0,steer:0,throttle:0,brake:0,wheelieInput:0,angle:0,angularVelocity:0,gear:0,rpm:1.2,fuel:save.fuel||82,x:0,z:0,distance:0,combo:0,bestCombo:0,score:0,mission:false,missionSeconds:0,missionDone:false,camera:save.camera||0,cameraYaw:0,weather:save.weather||0,clock:save.hour||16.7,paused:false,onFoot:false,freeCamera:false,showHUD:true};
