const mat=(color,roughness=.85,metalness=0)=>new THREE.MeshStandardMaterial({color,roughness,metalness});
const mats={asphalt:mat('#303633'),concrete:mat('#777c72'),sidewalk:mat('#92968a'),grass:mat('#58684c'),lane:mat('#d6d2b7'),yellow:mat('#dfc846'),window:mat('#80928a',.35,.15),windowLit:mat('#bca878',.3),wall1:mat('#b2a58a'),wall2:mat('#d4c7a6'),wall3:mat('#828d79'),wall4:mat('#c07e5d'),wall5:mat('#89928f'),roof:mat('#625d50'),dark:mat('#222927'),white:mat('#e2e2d7'),metal:mat('#66706b',.35,.75),rubber:mat('#171a19'),leaf:mat('#4b6545'),trunk:mat('#624c35'),red:mat('#b74e3f'),blue:mat('#3c6062'),green:mat('#64824f')};
const makeMesh=(geo,material,parent=scene)=>{const m=new THREE.Mesh(geo,material);m.castShadow=true;m.receiveShadow=true;parent.add(m);return m;};
function box(parent,x,y,z,sx,sy,sz,material){const m=makeMesh(new THREE.BoxGeometry(sx,sy,sz),material,parent);m.position.set(x,y,z);return m;}
