// Procedural Brazilian street grid, block-by-block architecture and street dressing.
box(world,0,-.52,0,500,1,500,mats.grass);
for(let v=-240;v<=240;v+=60){box(world,v,.005,0,14,.04,500,mats.asphalt);box(world,v-8,.055,0,2,.14,500,mats.sidewalk);box(world,v+8,.055,0,2,.14,500,mats.sidewalk);for(let z=-238;z<240;z+=12)box(world,v,.032,z, .16,.015,5,mats.lane);}
for(let v=-240;v<=240;v+=60){box(world,0,.005,v,500,.04,14,mats.asphalt);box(world,0,.055,v-8,500,.14,2,mats.sidewalk);box(world,0,.055,v+8,500,.14,2,mats.sidewalk);for(let x=-238;x<240;x+=12)box(world,x,.032,v,5,.015,.16,mats.lane);}
// intersection zebra markings, bumps and curb details
for(let x=-240;x<=240;x+=60)for(let z=-240;z<=240;z+=60){for(let i=-4;i<=4;i++)if(Math.abs(i)>1){box(world,x+i*1.1,.04,z-8.8,.68,.025,.5,mats.white);box(world,x+i*1.1,.04,z+8.8,.68,.025,.5,mats.white);}}
const buildingPositions=[];
for(let bx=-210;bx<210;bx+=60)for(let bz=-210;bz<210;bz+=60){
 if(Math.abs(bx)<38&&Math.abs(bz)<38)continue;
 const n=2+Math.floor(Math.random()*3);
 for(let j=0;j<n;j++){
  const w=9+Math.random()*12,d=9+Math.random()*12,h=5+Math.random()*(Math.abs(bx)+Math.abs(bz)<160?16:8);
  const x=bx-20+Math.random()*39,z=bz-20+Math.random()*39,levels=Math.max(1,Math.floor(h/3.3)),wall=pick([mats.wall1,mats.wall2,mats.wall3,mats.wall4,mats.wall5]);
  const b=box(world,x,h/2,z,w,h,d,wall);buildingPositions.push([x,z]);
  box(world,x,h+.13,z,w+.45,.28,d+.45,mats.roof);
  // Repeated window and balcony bands on street-facing facades.
  for(let floor=0;floor<levels;floor++){const yy=1.35+floor*3.1;if(yy>h-.5)continue;
   for(let wx=-w/2+1.25;wx<w/2-1;wx+=2.6){const winmat=Math.random()>.7?mats.windowLit:mats.window;box(world,x+wx,yy,z-d/2-.022,1.05,1.12,.05,winmat);if(Math.random()>.55)box(world,x+wx,yy-.68,z-d/2-.16,1.35,.08,.28,mats.metal);}
   for(let wz=-d/2+1.2;wz<d/2-1;wz+=2.8)box(world,x-w/2-.022,yy,z+wz,.05,1.1,1.05,mats.window);
  }
  if(Math.random()>.48){const sign=box(world,x,h*.2,z-d/2-.14,Math.min(w-1,6),.48,.16,pick([mats.red,mats.blue,mats.green]));sign.castShadow=false;}
 }
}
function palm(x,z,scale=1){const group=new THREE.Group();group.position.set(x,0,z);world.add(group);const trunk=makeMesh(new THREE.CylinderGeometry(.17*scale,.28*scale,5.6*scale,7),mats.trunk,group);trunk.position.y=2.8*scale;for(let i=0;i<7;i++){const a=i*Math.PI*2/7;const leaf=makeMesh(new THREE.ConeGeometry(.34*scale,4.2*scale,5),mats.leaf,group);leaf.position.set(Math.sin(a)*1.45*scale,5.4*scale,Math.cos(a)*1.45*scale);leaf.rotation.z=Math.cos(a)*.95;leaf.rotation.x=Math.sin(a)*.95;}}
function tree(x,z){const g=new THREE.Group();g.position.set(x,0,z);world.add(g);let t=makeMesh(new THREE.CylinderGeometry(.17,.24,2.4,6),mats.trunk,g);t.position.y=1.2;const top=makeMesh(new THREE.IcosahedronGeometry(1.7,1),mats.leaf,g);top.position.y=3;top.scale.set(1,1.2,.9);}
for(let v=-225;v<=225;v+=30){for(let side of [-1,1]){palm(v,side*10.4,.74);palm(side*10.4,v,.72);}}
for(let i=0;i<170;i++){const x=(Math.random()-.5)*430,z=(Math.random()-.5)*430;if(Math.abs(x%60)>12&&Math.abs(z%60)>12&&Math.hypot(x,z)>38){if(Math.random()>.35)tree(x,z);}}
// roadside lamps and traffic signals
const lampMat=mat('#303a34',.5,.4),glowMat=new THREE.MeshStandardMaterial({color:'#fff1ad',emissive:'#ffcf59',emissiveIntensity:2});
for(let x=-210;x<=210;x+=60)for(let side of [-1,1]){const xx=x+side*9.5;const pole=makeMesh(new THREE.CylinderGeometry(.065,.11,5.5,6),lampMat,world);pole.position.set(xx,2.75, (x%120===0?10:-10));const arm=box(world,xx+.75,5.3,(x%120===0?10:-10),1.5,.1,.1,lampMat);const lamp=makeMesh(new THREE.SphereGeometry(.15,8,6),glowMat,world);lamp.position.set(xx+1.45,5.15,(x%120===0?10:-10));}
// Small local storefronts and service station landmarks
function landmark(x,z,label,color){const g=new THREE.Group();g.position.set(x,0,z);world.add(g);box(g,0,2,0,13,4,9,mat(color));box(g,0,4.2,0,13,.4,9,mats.roof);box(g,0,2.4,-4.58,8,1.2,.08,mats.window);box(g,0,4.65,-4.7,11,.58,.2,mats.red);const canvas=document.createElement('canvas');canvas.width=512;canvas.height=96;const c=canvas.getContext('2d');c.fillStyle='#19211b';c.fillRect(0,0,512,96);c.fillStyle='#d4ff70';c.font='bold 54px Arial';c.textAlign='center';c.fillText(label,256,66);const texture=new THREE.CanvasTexture(canvas);const sign=makeMesh(new THREE.PlaneGeometry(10.5,1.8),new THREE.MeshBasicMaterial({map:texture}),g);sign.position.set(0,4.67,-4.82);}
landmark(-28,-28,'OFICINA 01','#7c7361');landmark(92,30,'POSTO VIA SUL','#708071');landmark(-91,92,'MERCADO BOM DIA','#ba9e72');landmark(151,-91,'BOX 77 · MOTOS','#8c7762');
// Physics-friendly custom motorcycle built from original geometry.
let bikePaint=mat(save.paint||bikeData[save.bike||0].color,.32,.28);let bikeRoot=new THREE.Group();scene.add(bikeRoot);
function wheel(parent,z){const pivot=new THREE.Group();pivot.position.set(0,.39,z);parent.add(pivot);const tire=makeMesh(new THREE.TorusGeometry(.36,.085,10,24),mats.rubber,pivot);tire.rotation.y=Math.PI/2;const rim=makeMesh(new THREE.TorusGeometry(.285,.024,7,24),mats.metal,pivot);rim.rotation.y=Math.PI/2;const hub=makeMesh(new THREE.CylinderGeometry(.075,.075,.22,12),mat('#aeb5aa',.32,.8),pivot);hub.rotation.z=Math.PI/2;for(let i=0;i<10;i++){const a=i*Math.PI*2/10;const spoke=makeMesh(new THREE.CylinderGeometry(.012,.012,.48,5),mats.metal,pivot);spoke.position.set(0,Math.sin(a)*.15,Math.cos(a)*.15);spoke.rotation.x=a;}for(let i=0;i<8;i++){const tread=makeMesh(new THREE.BoxGeometry(.012,.15,.035),mat('#343a36'),pivot);const a=i*Math.PI/4;tread.position.set(0,Math.sin(a)*.425,Math.cos(a)*.425);tread.rotation.x=a;}return pivot;}
let rearWheel,frontWheel,paintParts=[];
function makeBike(){bikeRoot.clear();paintParts=[];bikePaint=mat(save.paint||bikeData[save.bike||0].color,.32,.28);rearWheel=wheel(bikeRoot,.78);frontWheel=wheel(bikeRoot,-1.05);
 const frame=mat('#69726c',.3,.7),black=mat('#202624',.5,.2),seat=mat('#252a27');
 // frame rails, engine, swingarm
 for(const [a,b,r] of [[[0,.5,.75],[0,1.03,-.05],.055],[[0,.54,.75],[0,.91,-.77],.045],[[0,.92,-.72],[0,1.05,.17],.05],[[0,.5,.75],[0,.48,-.85],.06]]){const start=new THREE.Vector3(...a),end=new THREE.Vector3(...b),dir=end.clone().sub(start);const m=makeMesh(new THREE.CylinderGeometry(r*.78,r,dir.length(),8),frame,bikeRoot);m.position.copy(start.add(end).multiplyScalar(.5));m.quaternion.setFromUnitVectors(new THREE.Vector3(0,1,0),dir.normalize());}
 const eng=makeMesh(new THREE.BoxGeometry(.58,.58,.64),mat('#555d57',.4,.55),bikeRoot);eng.position.set(0,.76,.14);const caseCover=makeMesh(new THREE.CylinderGeometry(.22,.22,.11,12),mats.metal,bikeRoot);caseCover.rotation.z=Math.PI/2;caseCover.position.set(.32,.75,.22);
 const tank=makeMesh(new THREE.SphereGeometry(1,18,12),bikePaint,bikeRoot);tank.position.set(0,1.2,-.25);tank.scale.set(.36,.36,.63);paintParts.push(tank);
 const shroud=makeMesh(new THREE.BoxGeometry(.69,.46,.39),bikePaint,bikeRoot);shroud.position.set(0,.99,-.75);shroud.rotation.x=-.14;paintParts.push(shroud);
 const saddle=makeMesh(new THREE.BoxGeometry(.42,.14,1.05),seat,bikeRoot);saddle.position.set(0,1.16,.52);saddle.rotation.x=-.08;
 const tail=makeMesh(new THREE.BoxGeometry(.42,.24,.46),bikePaint,bikeRoot);tail.position.set(0,1.32,.92);tail.rotation.x=-.18;paintParts.push(tail);
 // fork tubes, shocks, handlebar
 for(let side of [-1,1]){const fork=makeMesh(new THREE.CylinderGeometry(.045,.06,1.02,9),mats.metal,bikeRoot);fork.position.set(side*.16,.89,-.88);fork.rotation.x=-.18;const shock=makeMesh(new THREE.CylinderGeometry(.05,.07,.8,8),mat('#c2c7ba',.3,.7),bikeRoot);shock.position.set(side*.18,.83,.66);shock.rotation.x=-.12;}
 const handle=makeMesh(new THREE.CylinderGeometry(.035,.035,.76,8),mats.dark,bikeRoot);handle.rotation.z=Math.PI/2;handle.position.set(0,1.55,-.84);
 for(let side of [-1,1]){const grip=makeMesh(new THREE.CylinderGeometry(.065,.065,.2,9),mats.rubber,bikeRoot);grip.rotation.z=Math.PI/2;grip.position.set(side*.43,1.55,-.84);const mirrorStem=makeMesh(new THREE.CylinderGeometry(.018,.018,.28,6),frame,bikeRoot);mirrorStem.position.set(side*.24,1.69,-.88);mirrorStem.rotation.z=side*-.5;const mirror=makeMesh(new THREE.SphereGeometry(.085,10,7),mats.metal,bikeRoot);mirror.scale.set(.18,1,.65);mirror.position.set(side*.3,1.82,-.91);}
 // exhaust and lamps
 const exhaust=makeMesh(new THREE.CylinderGeometry(.1,.14,.95,10),mat('#747b76',.3,.75),bikeRoot);exhaust.rotation.x=Math.PI/2;exhaust.position.set(.3,.72,.92);
 const head=makeMesh(new THREE.SphereGeometry(.18,12,8),new THREE.MeshStandardMaterial({color:'#fff5cc',emissive:'#fff0af',emissiveIntensity:1.8}),bikeRoot);head.scale.set(1,.7,.5);head.position.set(0,1.38,-1.01);
 const tailLight=makeMesh(new THREE.BoxGeometry(.24,.1,.09),new THREE.MeshStandardMaterial({color:'#ed4537',emissive:'#a5140b',emissiveIntensity:1.1}),bikeRoot);tailLight.position.set(0,1.41,1.17);
 // rider torso, limbs and helmet (simple custom rig proportions)
 const rider=new THREE.Group();rider.name='rider';bikeRoot.add(rider);const jacket=mat('#313b35'),pants=mat('#262b29'),skin=mat('#b97e5d'),helmetMat=mat('#202723',.24,.38);
 const torso=makeMesh(new THREE.CapsuleGeometry(.22,.42,4,8),jacket,rider);torso.position.set(0,1.79,.23);torso.rotation.x=-.32;
 const pelvis=makeMesh(new THREE.BoxGeometry(.38,.22,.35),pants,rider);pelvis.position.set(0,1.42,.51);
 for(let side of [-1,1]){const arm=makeMesh(new THREE.CylinderGeometry(.075,.1,.53,8),jacket,rider);arm.position.set(side*.27,1.72,-.16);arm.rotation.x=-.75;arm.rotation.z=side*.2;const leg=makeMesh(new THREE.CylinderGeometry(.095,.12,.55,8),pants,rider);leg.position.set(side*.19,1.16,.69);leg.rotation.x=-.52;const boot=makeMesh(new THREE.BoxGeometry(.17,.13,.3),mats.dark,rider);boot.position.set(side*.2,.92,.4);}
 const neck=makeMesh(new THREE.CylinderGeometry(.09,.1,.16,8),skin,rider);neck.position.set(0,2.08,.04);const helmet=makeMesh(new THREE.SphereGeometry(.23,14,10),helmetMat,rider);helmet.position.set(0,2.29,-.06);helmet.scale.set(1,1.08,1.03);const visor=makeMesh(new THREE.BoxGeometry(.32,.09,.16),mat('#73847c',.18,.5),rider);visor.position.set(0,2.3,-.25);
}
makeBike();
const traffic=[];const carMats=['#c5c6b7','#6a7774','#b64f3f','#313b3a','#d2b653'].map(c=>mat(c,.35,.24));
function makeCar(x,z,heading){const g=new THREE.Group();scene.add(g);const body=makeMesh(new THREE.BoxGeometry(1.65,.62,3.35),pick(carMats),g);body.position.y=.6;const cabin=makeMesh(new THREE.BoxGeometry(1.4,.58,1.8),mat('#687b79',.24,.3),g);cabin.position.set(0,1.15,-.15);for(let side of [-1,1])for(let f of [-1,1]){const w=makeMesh(new THREE.CylinderGeometry(.31,.31,.16,12),mats.rubber,g);w.rotation.z=Math.PI/2;w.position.set(side*.86,.34,f*1.08);}g.position.set(x,0,z);g.rotation.y=heading;traffic.push({g,x,z,heading,speed:5+Math.random()*5,lane:Math.random()});}
for(let i=0;i<22;i++){let axis=Math.random()>.5;const line=(Math.floor(Math.random()*7)-3)*60;let x,z,h;if(axis){x=line+(Math.random()-.5)*3;z=(Math.random()-.5)*410;h=Math.random()>.5?0:Math.PI;}else{z=line+(Math.random()-.5)*3;x=(Math.random()-.5)*410;h=Math.random()>.5?Math.PI/2:-Math.PI/2;}makeCar(x,z,h);}
// Rain particles are dormant until selected; updated in-place for low allocation.
const rainCount=700,rainGeo=new THREE.BufferGeometry(),rainPos=new Float32Array(rainCount*3);for(let i=0;i<rainCount;i++){rainPos[i*3]=(Math.random()-.5)*45;rainPos[i*3+1]=Math.random()*24;rainPos[i*3+2]=(Math.random()-.5)*45;}rainGeo.setAttribute('position',new THREE.BufferAttribute(rainPos,3));const rain=new THREE.Points(rainGeo,new THREE.PointsMaterial({color:'#d7e6eb',size:.09,transparent:true,opacity:.62}));rain.visible=false;scene.add(rain);
// Surface smoke particles while doing a controlled burnout.
const dust=[];function puff(){if(dust.length>65)return;const m=makeMesh(new THREE.SphereGeometry(.08+Math.random()*.1,6,5),new THREE.MeshBasicMaterial({color:'#c6c5b7',transparent:true,opacity:.28,depthWrite:false}),scene);m.position.set(state.x,.16,state.z+.8);dust.push({m,life:1,dx:(Math.random()-.5)*.8,dy:.3+Math.random()*.4,dz:Math.random()*.7});}

function paintBike(color){save.paint=color;bikePaint.color.set(color);paintParts.forEach(p=>p.material.color.set(color));persist();$$('.color-dot').forEach(x=>x.classList.toggle('active',x.dataset.color.toLowerCase()===color.toLowerCase()));}
function activeBike(){return bikeData[save.bike]||bikeData[0];}
function syncBikeCard(){const b=activeBike();$('#bike-name').innerHTML=b.name.replace(' ','<br><em>')+'</em>';$('#bike-class').textContent=b.class;$('#bike-power').textContent=b.power;$('#bike-max').textContent=b.max;paintBike(save.paint||b.color);}
syncBikeCard();
function updateWallet(){$('#cash-value').textContent=(save.cash||0).toLocaleString('pt-BR');}
updateWallet();
function toast(msg){const el=$('#toast');el.textContent=msg;el.classList.add('visible');clearTimeout(toast.timer);toast.timer=setTimeout(()=>el.classList.remove('visible'),2200);}
function setPanel(panel){const overlay=$('#panel-overlay'),content=$('#panel-content');if(!panel){overlay.classList.remove('open');overlay.setAttribute('aria-hidden','true');$$('.nav-item').forEach(n=>n.classList.toggle('active',n.dataset.panel==='ride'));return;}overlay.classList.add('open');overlay.setAttribute('aria-hidden','false');$$('.nav-item').forEach(n=>n.classList.toggle('active',n.dataset.panel===panel));content.innerHTML=panelContent(panel);content.dataset.panel=panel;}
function panelContent(panel){
